mcp:tool-listener.mcp:parameters-schema:
{
  "$schema": "# SECURITY: Remote schema removed (http://json-schema.org/draft-07/schema#)",
  "title": "Send Travel Request",
  "type": "object",
  "properties": {
    "userMessage": {
      "type": "string",
      "description": "The travel request message from the user"
    },
    "slackChannel": {
      "type": "string",
      "description": "The Slack channel ID to post the response to"
    },
    "slackUser": {
      "type": "string",
      "description": "The Slack user ID who initiated the request"
    }
  },
  "required": ["userMessage", "slackChannel"]
}

ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
  channel: vars.slackChannel,
  blocks: [
    {
      "type": "section",
      text: {
        "type": "mrkdwn",
        text: ":airplane: *Travel Assistant:*\n" ++ (vars.userMessage default "Travel request is being processed!")
      }
    }
  ]
}
